#include "phase_forms.hpp"
#include <memory>
struct P {vector<Gate> gates; int kind; unsigned dim;};
optional<P> joint(Gate a,vector<Gate>const&between,Gate b,U scratch){
 if(!(a.op&128)||!(b.op&128)||a.cond==b.cond)return nullopt;
 for(auto h:between)if(h.op==64 && h.bit==b.cond)return nullopt;
 array<Form,6> f{{{unit(a.a)},{unit(a.b)},{unit(a.t)},{unit(b.a)},{unit(b.b)},{unit(b.t)}}};
 for(auto it=between.rbegin();it!=between.rend();it++)if(lin(*it))for(int j=3;j<6;j++)pull(f[j],*it);
 Basis S;for(auto z:f)S.insert(z.v);unsigned d=S.vs.size();
 array<unsigned,3>A{},D{};for(int j=0;j<3;j++){A[j]=S.coord(f[j].v);D[j]=S.coord(f[j+3].v);}auto sa=span(A),sb=span(D);vector<unsigned> inter;set_intersection(sa.begin(),sa.end(),sb.begin(),sb.end(),back_inserter(inter));
 if(inter.size()!=3&&inter.size()!=7)return nullopt;
 auto decode=[&](unsigned z){V v;for(unsigned j=0;j<d;j++)if(z>>j&1)v^=S.vs[j];return v;};
 bool same=inter.size()==7;array<unsigned,4> chosen{};if(same)chosen={A[0],A[1],A[2],0};else{chosen[0]=inter[0];chosen[1]=inter[1];for(auto z:sa)if(!binary_search(inter.begin(),inter.end(),z)){chosen[2]=z;break;}for(auto z:sb)if(!binary_search(inter.begin(),inter.end(),z)){chosen[3]=z;break;}}
 Basis N;for(auto z:chosen)if(z)N.insert(decode(z));for(auto z:S.vs)N.insert(z);assert(N.vs.size()==d);array<unsigned,6> coef{};for(int j=0;j<6;j++)coef[j]=N.coord(f[j].v);
 vector<Gate> pre,out;vector<U> pp;vector<V> row=N.vs;for(unsigned j=0;j<d;j++){U p=0;while(p<900&&(!row[j][p]||find(pp.begin(),pp.end(),p)!=pp.end()))p++;assert(p<900);V v=row[j];v.reset(p);for(U k=0;k<900;k++)if(v[k])pre.push_back({33,k,p});for(unsigned k=j+1;k<d;k++)if(row[k][p])row[k]^=v;pp.push_back(p);}
 vector<V> actual(900);for(U i=0;i<900;i++)actual[i]=unit(i);for(auto g:pre)actual[g.b]^=actual[g.a];for(unsigned j=0;j<d;j++)assert(actual[pp[j]]==N.vs[j]);
 array<vector<unsigned char>,2> residual,orig;for(int side=0;side<2;side++){auto &r=residual[side],&o=orig[side];r.resize(1u<<d);o.resize(1u<<d);unsigned m=side&&!same?11:7;for(unsigned x=0;x<r.size();x++){unsigned t=1;for(int j=0;j<3;j++)t&=parity(x&coef[3*side+j])^f[3*side+j].c;o[x]=t;r[x]=t^((x&m)==m);}for(unsigned j=0;j<d;j++)for(unsigned x=0;x<r.size();x++)if(x>>j&1)r[x]^=r[x^(1u<<j)];for(unsigned x=0;x<r.size();x++)if(__builtin_popcount(x)>2)assert(!r[x]);}
 U any=scratch,both=scratch+1,onlyb=scratch+2;auto clear=[&](U q){out.push_back({64,0,0,0,q});};auto store=[&](U q,bool v,U c){out.push_back({(unsigned char)((v?65:64)|128),0,0,0,q,c});};clear(any);
 if(same){out.push_back({194,0,0,0,any,a.cond});out.push_back({194,0,0,0,any,b.cond});}else{store(any,true,a.cond);store(any,true,b.cond);clear(both);out.push_back({129,0,0,0,0,a.cond});store(both,true,b.cond);out.push_back({1});clear(onlyb);store(onlyb,true,b.cond);store(onlyb,false,a.cond);}
 out.insert(out.end(),pre.begin(),pre.end());auto phase=[&](int op,U c,U x,U y=0,U z=0){out.push_back({(unsigned char)(op|128),x,y,z,0,c});};
 for(int side=0;side<2;side++){U c=side?b.cond:a.cond;auto &r=residual[side];for(unsigned m=0;m<r.size();m++)if(r[m]){if(m==0){out.push_back({17,pp[0]});phase(16,c,pp[0]);out.push_back({17,pp[0]});phase(16,c,pp[0]);}else if(__builtin_popcount(m)==1)phase(16,c,pp[__builtin_ctz(m)]);else{unsigned i=__builtin_ctz(m),j=__builtin_ctz(m^(1u<<i));phase(32,c,pp[i],pp[j]);}}}
 if(!same){out.push_back({162,pp[2],pp[3],0,0,onlyb});out.push_back({161,pp[3],pp[2],0,0,both});}phase(48,any,pp[0],pp[1],pp[2]);if(!same){out.push_back({161,pp[3],pp[2],0,0,both});out.push_back({162,pp[2],pp[3],0,0,onlyb});}out.insert(out.end(),pre.rbegin(),pre.rend());clear(any);if(!same){clear(both);clear(onlyb);}
 for(unsigned x=0;x<(1u<<d);x++)for(bool ga:{false,true})for(bool gb:{false,true}){unsigned y=x;bool p=0;for(int side=0;side<2;side++)if(side?gb:ga)for(unsigned m=0;m<residual[side].size();m++)if(residual[side][m]&&(x&m)==m)p^=1;if(same)p^=(ga^gb)&&((x&7)==7);else{if(!ga&&gb){bool c=(y>>2)&1,e=(y>>3)&1;if(c!=e)y^=12;}if(ga&&gb&&((y>>3)&1))y^=4;p^=(ga||gb)&&((y&7)==7);if(ga&&gb&&((y>>3)&1))y^=4;if(!ga&&gb){bool c=(y>>2)&1,e=(y>>3)&1;if(c!=e)y^=12;}}assert(y==x&&p==((ga&&orig[0][x])^(gb&&orig[1][x])));}
 return P{out,same?2:1,d};
}
int main(int argc,char**argv){assert(argc==2||argc==3);Reader r(argv[1]);assert(r.Q==900);optional<Gate> prev;L pi=0,tries=0,matched=0;vector<Gate> between;map<int,L> stats;map<int,L> dims;unique_ptr<Writer>w;if(argc==3)w=make_unique<Writer>(r,r.B+3);auto put=[&](Gate g){if(w)w->put(g);};auto flush=[&](){if(prev)put(*prev);for(auto g:between)put(g);prev.reset();between.clear();};ofstream cert("joint_sites.tsv");for(L i=0;i<r.counts[0];i++){auto g=r.read(i);if((g.op&127)==48){if(prev){tries++;auto p=joint(*prev,between,g,r.B);if(p){matched++;stats[p->kind]++;dims[p->dim]++;cert<<pi<<'\t'<<i<<'\t'<<p->kind<<'\t'<<p->dim<<'\t'<<prev->cond<<'\t'<<g.cond<<'\n';for(auto h:p->gates)put(h);for(auto h:between)put(h);prev.reset();between.clear();continue;}flush();}prev=g;pi=i;}else if(prev&&(lin(g)||diagonal(g)||g.op==64)){between.push_back(g);if(between.size()>5000)flush();}else{flush();put(g);}}flush();cerr<<"pairs "<<tries<<" matched "<<matched<<"\n";for(auto [k,n]:stats)cerr<<"kind "<<k<<" "<<n<<"\n";for(auto [k,n]:dims)cerr<<"dim "<<k<<" "<<n<<"\n";if(w&&matched){assert(w->a[2].size()+matched==r.counts[1]);w->write(argv[2]);cerr<<"paid "<<r.counts[1]<<" -> "<<w->a[2].size()<<" ops "<<r.counts[0]<<" -> "<<w->ops.size()<<"\n";}}
